/* Standard Isolation Forest c(n): expected unsuccessful-BST-search path
 * length for n points. Matches ml/export_embedded.py's average_path_length_c().
 * Only called with n>=1 at runtime (leaf sample counts), so no n==0 case. */
static float anomaly_model_c(float n) {
    if (n <= 1.0f) return 0.0f;
    if (n == 2.0f) return 1.0f;
    float harmonic = logf(n - 1.0f) + 0.5772156649f;
    return 2.0f * harmonic - 2.0f * (n - 1.0f) / n;
}

static float anomaly_model_tree_path_length(const IsolationTree_t *tree, const float *x) {
    int16_t node = 0;
    int16_t depth = 0;
    while (tree->feature[node] >= 0) {  /* -2 marks a leaf */
        int16_t f = tree->feature[node];
        node = (x[f] <= tree->threshold[node]) ? tree->left[node] : tree->right[node];
        depth++;
    }
    return (float)depth + anomaly_model_c((float)tree->n_node_samples[node]);
}

/* x must have ANOMALY_MODEL_N_FEATURES elements, in the exact order documented
 * at the top of this file. Returns a score in roughly [0,1]; values closer to
 * 1.0 indicate anomalous input (paper convention -- see file header). This
 * function only latches FaultFlag.ML_ANOMALY through fdir's normal debounce
 * gate; it must never be wired to directly change flight-computer mode. */
static float isolation_forest_score(const float *x) {
    float total_path_length = 0.0f;
    for (int i = 0; i < ANOMALY_MODEL_N_TREES; i++) {
        total_path_length += anomaly_model_tree_path_length(&ANOMALY_MODEL_TREES[i], x);
    }
    float avg_path_length = total_path_length / (float)ANOMALY_MODEL_N_TREES;
    return powf(2.0f, -avg_path_length / ANOMALY_MODEL_C_NORM);
}

